def classify(reading):
    if reading is None:
        return "missing"
    if type(reading) is bool:
        return "flag"
    if type(reading) is int:
        return "count"
    if type(reading) is float:
        return "measure"
    if not reading:
        return "blank"
    return "text"


print(classify(1.5))
